<style>
*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#111827;font-family:Arial,Helvetica,sans-serif}.print-toolbar{max-width:210mm;margin:12px auto 0;display:flex;justify-content:flex-end;gap:8px}.print-toolbar button{border:1px solid #64748b;background:#fff;padding:8px 14px;font-weight:700;cursor:pointer}.print-toolbar button.primary{background:#064e3b;color:#fff;border-color:#064e3b}.paper{width:210mm;min-height:280mm;margin:8px auto 24px;background:#fff;padding:12mm;box-shadow:0 4px 18px rgba(15,23,42,.12)}.company{text-align:center;border-bottom:2px solid #111827;padding-bottom:8px}.company h1{font-size:22px;margin:0}.company p{margin:4px 0 0;font-size:12px}.doc-title{text-align:center;font-size:16px;font-weight:800;margin:12px 0}.meta{width:100%;border-collapse:collapse;font-size:12px}.meta td{padding:5px 6px;border:1px solid #cbd5e1}.meta td.label{width:18%;background:#f1f5f9;font-weight:700}.grid{width:100%;border-collapse:collapse;margin-top:10px;font-size:11px}.grid th,.grid td{border:1px solid #94a3b8;padding:6px}.grid th{background:#e2e8f0;text-align:left}.num{text-align:right}.totals{margin-left:auto;margin-top:12px;width:290px;border-collapse:collapse;font-size:12px}.totals td{border:1px solid #94a3b8;padding:7px}.totals td:first-child{font-weight:700;background:#f8fafc}.footer{margin-top:28px;padding-top:8px;border-top:1px solid #cbd5e1;font-size:10px;color:#64748b}.strong{font-weight:800}.balance{font-size:15px;font-weight:900}@media print{body{background:#fff}.print-toolbar{display:none}.paper{width:auto;min-height:0;margin:0;padding:0;box-shadow:none}@page{size:A4 portrait;margin:12mm}}
</style>
